SELECT OrderID FROM orders LIMIT 10;
select * from order_summary limit 10;
select count(*) as totalrows from order_summary;

select * from orders;
select * from order_items;

select sum(quantity * unitprice) as revenue from order_items;
select max(profit) from order_items where profit < (select max(profit) from order_items);
select orderid,productid from (select orderid,productid, dense_rank() over (partition by orderid order by profit desc ) 
as maxprice from order_items) t where  maxprice = 2;

-- sql business analysis --
-- Revenue -- 
select sum(profit) as revenue 
from order_items;

-- Order_count --
select count(distinct orderid) 
from orders;

-- Total_customers --
select count( customerid) as total_customers 
from customers;

-- Total_products --
select count(productid) as total_products 
from products;

-- kip query --
select 
(select sum(profit) as revenue from order_items) as revenue,
(select count(distinct orderid) from orders) as order_count,
(select count( customerid) as total_customers from customers )as total_customers,
(select count(productid) as total_products from products) as total_products ;

-- Top 5 Products by Revenue -- 

select p.productid,p.productname,p.category,sum(oi.quantity * oi.unitprice) as revenue 
from products p 
join order_items oi on p.productid = oi.productid
group by p.productid,p.productname
order by revenue desc 
limit 5;

-- Revenue by Category --

select p.productname,p.category, sum(oi.quantity * oi.unitprice) as revenue 
from products p 
join order_items oi on 
p.productid = oi.productid
group by p.category ,p.productname
order by revenue desc;

-- Monthly Sales Revenue -- 

select 
year(o.orderdate) as sales_year,
month(o.orderdate) as sales_month,
monthname(o.orderdate) as sales_month_name,
sum(oi.quantity * oi.unitprice) as total_revenue
from orders o 
join order_items oi on
o.orderid = oi.orderid
where o.orderdate is not null
group by sales_month_name ,sales_year,sales_month
order by total_revenue desc;

-- Monthly Order Count -- 
select 
year(o.orderdate) as sales_year,
month(o.orderdate) as sales_month,
monthname(o.orderdate) as sales_month_name,
sum(oi.quantity * oi.unitprice) as total_revenue
from orders o join order_items oi on
o.orderid = oi.orderid
where o.orderdate is not null
group by 
year(orderdate),month (orderdate),monthname(orderdate)
order by 
sales_year,sales_month,sales_month_name;

-- Monthly Order Count -- 
select 
year(orderdate) as sales_year,
month (orderdate) as sales_month,
monthname(orderdate) as sales_month_name,
count(distinct orderid ) as order_count
from orders
where orderdate is not null
group by 
year(orderdate),month (orderdate),monthname(orderdate)
order by 
sales_year,sales_month,sales_month_name;

-- Customer Analysis --
-- Find Customers with the Highest Revenue --

select c.customername,count(distinct o.orderid)as order_count, sum(oi.quantity * oi.unitprice) as total_revenue 
from customers c
join orders o
on c.customerid = o.customerid 
join order_items oi 
on o.orderid = oi.orderid
group by c.customername ,o.orderdate
order by total_revenue desc
limit 10;

-- Customers who have never placed an order -- 
select c.customerid, c.city,c.state,c.region 
from customers c 
left join orders o 
on c.customerid = o.customerid
where orderid is null;
 
 -- Payment Analysis -- 
 -- Revenue by Payment Method -- 
 select orderid,paymentmethod, sum(amount) as total_revenue
 from payment 
 group by paymentmethod ,orderid 
 order by total_revenue desc;
 
 -- Payment Status Analysis -- 
 select count(orderid),paymentmethod,paymentstatus, sum(amount) as total_revenue
 from payment 
 group by paymentmethod ,orderid,paymentstatus 
 order by total_revenue desc ; 
 
-- payment Method + Status --

select paymentmethod,paymentstatus, sum(amount) as total_revenue 
from payment 
group by paymentmethod,paymentstatus 
order by total_revenue desc;

-- Returns Analysis. -- 

-- Total Returns -- 
select count(*) as total_returns 
from returns;

-- Returns by Reason -- 
select returnreason , count(*) as total_returns 
from returns
group by  returnreason
order by total_returns desc;

-- Returns by Status --
select returnstatus , count(*) as total_returns 
from returns 
group by returnstatus
order by total_returns desc;

-- Returns by Month  --
select 
year(returndate) as return_year,
month(returndate) as return_month ,
monthname(returndate) as return_month_name,
count(*) as total_return
from returns
where returndate is not null
group by month(returndate),monthname(returndate),year(returndate)
order by return_year,return_month,return_month_name,total_return desc;

-- category + Sales + Returns analysis --
-- Category Revenue and Quantity Sold --

select p.productname,p.category, sum(oi.quantity * oi.quantity) as total_revenue, oi.quantity 
from products p 
join order_items oi on 
p.productid = oi.productid
group by p.productname,p.category,oi.quantity
order by total_revenue desc
limit 10;

-- Find returned orders and their revenue --
select r.returnid,r.returnstatus,r.returnreason, sum(oi.profit)as total_revenue
from returns r
join order_items oi on 
r.orderid = oi.orderid
group by r.returnid,r.returnstatus,r.returnreason
order by total_revenue desc 
limit 10;

-- Return rate --
select count(distinct r.orderid) as return_count,
count(distinct o.orderid) as order_count,
round(count(distinct r.orderid) * 100.0 / count(distinct o.orderid),2) as return_rate_percenatge
from orders o 
left join returns r 
on r. orderid = o.orderid;

-- SQL Window Functions. --
-- Rank Products by Revenue --

select p.productname,p.category,sum(oi.profit) as total_revenue, 
rank () over ( order by sum(oi.profit) desc) as rank_products 
from products p 
join order_items oi on 
p.productid = oi.productid
group by p.productname,p.category
order by rank_products ;
 
 -- Rank Products Within Each Category--
select p.productname,p.category,sum(oi.profit) as total_revenue, 
rank () over ( order by sum(oi.profit) desc) as rank_category 
from products p 
join order_items oi on 
p.productid = oi.productid
group by p.productname,p.category
order by rank_category ;

-- Assign a unique number to each product -- 
select p.productname, p.category , sum(oi.profit) as revenue,
row_number() over ( order by sum(oi.profit) desc ) as revenue_products 
from products p join order_items oi on p.productid = oi.productid
group by p.productname, p.category
order by revenue_products;

-- Top 3 products from each category --
with product_revenue as (
select p.productname,p.category,sum(oi.profit) as revenue 
from products p join order_items oi on p.productid = oi.productid
group by p.productname, p.category ),
rankedproducts as (
select productname,category, rank () over (partition by category order by revenue desc) as rankpro
from product_revenue ) 
select * from rankedproducts where rankpro >= 3;

-- create a Product Revenue CTE -- 
with product_revenue as(
select p.productname,p.category , sum(oi.profit) as revenue 
from products p 
join order_items oi on 
p.productid = oi .productid
group by  p.productname,p.category )
select * from product_revenue order by revenue desc;

-- Find products above average revenue -- 
with product_revenue as( 
select p.productname,p.category , sum(oi.profit) as revenue 
from products p 
join order_items oi on 
p.productid = oi .productid
group by  p.productname,p.category )
select productname, category , revenue 
from product_revenue 
where revenue > (select avg(revenue) from product_revenue )order by revenue desc;

-- Total Revenue generated by the customer -- 
select c.customername,sum(oi.profit) as revenue,
count(distinct oi.orderid) as count_orders from customers c join orders o on c.customerid = o.customerid
join order_items oi on o.orderid  = oi.orderid 
group by c.customername
order by revenue desc;

-- Top 10 Customers by CLV--

select c.customername,sum(oi.profit) as revenue,
count(distinct oi.orderid) as count_orders 
from customers c 
join orders o 
on c.customerid = o.customerid
join order_items oi on o.orderid  = oi.orderid 
group by c.customername
order by revenue desc
limit 10;

-- Average Customer CLV--

with customer_revenue as (
select c.customername,
sum(oi.profit) as revenue
from customers c 
join orders o on c.customerid = o.customerid
join order_items oi on o.orderid  = oi.orderid 
group by c.customername)
select round( avg(revenue),2) as avgcustomer_revenue
from customer_revenue;

-- Repeat vs One-Time Customers. --
-- Classify customers --
select c.customername,
count(distinct o.orderid)  as total_orders,
case 
when count(distinct o.orderid) = 1 then 'one time customer'
when count(distinct o.orderid) >1 then " Repeat customer"
end as customer_type
from customers c 
join orders o on c.customerid = o.customerid
group by c.customername
order by total_orders desc;

-- Count One-Time vs Repeat Customers --
select customerid,count(*) as customer_count 
from ( 
select c.customerid , 
case
when count(distinct o.orderid) = 1 then 'one time customer'
when count(distinct o.orderid) >1 then " Repeat customer"
end as customer_type
from customers c 
join orders o on 
c.customerid = o.customerid
group by c.customerid) as customer_classification 
group by customerid;

-- Repeat Customer Percentage -- 
WITH CustomerClassification AS (
    SELECT
        c.CustomerID,
        COUNT(DISTINCT o.OrderID) AS TotalOrders
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    GROUP BY c.CustomerID
)
SELECT
    COUNT(*) AS TotalCustomers,
    SUM(CASE WHEN TotalOrders > 1 THEN 1 ELSE 0 END) AS RepeatCustomers,
    ROUND(
        SUM(CASE WHEN TotalOrders > 1 THEN 1 ELSE 0 END) * 100.0
        / COUNT(*),
        2
    ) AS RepeatCustomerPercentage
FROM CustomerClassification;

-- Running Total and Moving Average. -- 

with monthly_revenue as(
select 
month(o.orderdate) as month_order,
year(o.orderdate) as year_order,
monthname(o.orderdate) as monthname_order,
sum(oi.profit) as revenue
from orders o 
join order_items oi
on o.orderid = oi.orderid 
group by month(o.orderdate),year(o.orderdate),monthname(o.orderdate))
select * from monthly_revenue order by month_order,year_order,monthname_order;

-- Running Total --
with monthly_revenue as(
select 
month(o.orderdate) as month_order,
year(o.orderdate) as year_order,
monthname(o.orderdate) as monthname_order,
sum(oi.profit) as revenue
from orders o 
join order_items oi
on o.orderid = oi.orderid 
group by month(o.orderdate),year(o.orderdate),monthname(o.orderdate))
select 
month_order,year_order,monthname_order,revenue,sum(revenue) over
 (order by month_order,year_order,monthname_order) running_revenue 
 from monthly_revenue 
 order by month_order,year_order,monthname_order;
 
 -- Month Moving Average --
 
 WITH MonthlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        MONTH(o.OrderDate) AS SalesMonth,
        MONTHNAME(o.OrderDate) AS MonthName,
        SUM(oi.profit) AS MonthlyRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY
        YEAR(o.OrderDate),
        MONTH(o.OrderDate),
        MONTHNAME(o.OrderDate)
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    MonthlyRevenue,
    ROUND(
        AVG(MonthlyRevenue) OVER (
            ORDER BY SalesYear, SalesMonth
            ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
        ),
        2
    ) AS ThreeMonthMovingAverage
FROM MonthlySales
ORDER BY SalesYear, SalesMonth;

-- Running Total Revenue --

WITH MonthlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        MONTH(o.OrderDate) AS SalesMonth,
        MONTHNAME(o.OrderDate) AS MonthName,
        SUM(oi.profit) AS MonthlyRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY
        YEAR(o.OrderDate),
        MONTH(o.OrderDate),
        MONTHNAME(o.OrderDate)
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    MonthlyRevenue,
    SUM(MonthlyRevenue) OVER (
        ORDER BY SalesYear, SalesMonth
    ) AS RunningRevenue
FROM MonthlySales
ORDER BY SalesYear, SalesMonth;

-- Month Moving Average. --
WITH MonthlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        MONTH(o.OrderDate) AS SalesMonth,
        MONTHNAME(o.OrderDate) AS MonthName,
        SUM(oi.profit) AS MonthlyRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY
        YEAR(o.OrderDate),
        MONTH(o.OrderDate),
        MONTHNAME(o.OrderDate)
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    MonthlyRevenue,
    ROUND(
        AVG(MonthlyRevenue) OVER (
            ORDER BY SalesYear, SalesMonth
            ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
        ),
        2
    ) AS ThreeMonthMovingAverage
FROM MonthlySales
ORDER BY SalesYear, SalesMonth;

-- Year-over-Year (YoY) Revenue Growth. --
WITH YearlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        SUM(oi.profit) AS TotalRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY YEAR(o.OrderDate)
)
SELECT
    SalesYear,
    TotalRevenue
FROM YearlySales
ORDER BY SalesYear;

-- Previous Year's Revenue --
WITH YearlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        SUM(oi.profit) AS TotalRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY YEAR(o.OrderDate)
)
SELECT
    SalesYear,
    TotalRevenue,
    LAG(TotalRevenue) OVER (
        ORDER BY SalesYear
    ) AS PreviousYearRevenue
FROM YearlySales
ORDER BY SalesYear;

-- Calculate YoY Growth % --

WITH YearlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        SUM(oi.profit) AS TotalRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY YEAR(o.OrderDate)
),
YearComparison AS (
    SELECT
        SalesYear,
        TotalRevenue,
        LAG(TotalRevenue) OVER (
            ORDER BY SalesYear
        ) AS PreviousYearRevenue
    FROM YearlySales
)
SELECT
    SalesYear,
    TotalRevenue,
    PreviousYearRevenue,
    ROUND(
        (TotalRevenue - PreviousYearRevenue)
        * 100.0 / NULLIF(PreviousYearRevenue, 0),
        2
    ) AS YoYGrowthPercent
FROM YearComparison
ORDER BY SalesYear;

-- Find customers with their order count --
use ecommerce_analytics_project;

select c.customerid,c.customername,count(distinct o.orderid) as order_count 
from customers c 
join orders o 
on 
c.customerid = o.customerid
group by c.customerid,c.customername
order by order_count desc;

-- Classify Customers --

select c.customerid , c.customername,count(distinct o.orderid) as total_orders,
case
when count(distinct orderid) = 1 then 'one time customer'
when count(distinct orderid) > 1 then 'repeat customer'
end as customer_type
from customers c
join orders o on 
c.customerid = o.customerid
group by  c.customerid , c.customername
order by total_orders desc;

-- Repeat Customer Percentage --

with customer_classification as (
select c.customerid , c.customername,count(distinct o.orderid) as total_orders
from customers c
join orders o on 
c.customerid = o.customerid
group by  c.customerid , c.customername) 
select count(*) as total_customers,
sum( case
when total_orders > 1 then 1
else 0
end ) as repeat_customers,
round(sum( case when total_orders > 1 then 1
else 0
end) * 100.0 / count(*) ,2) as customer_percentage
from customer_classification;

-- Customer Segmentation by Revenue --

select c.customerid,c.customername,count(distinct o.orderid) as order_count ,sum(oi.profit) as total_revenue
from customers c 
join orders o
on  c.customerid= o.customerid
join order_items oi on
o.orderid = oi.orderid
group by c.customerid,c.customername
order by total_revenue desc;

-- Customer Revenue Segmentation --

with customer_revenue as(
select c.customerid,c.customername,sum(oi.profit) as revenue 
from customers c 
join orders o
on  c.customerid= o.customerid
join order_items oi on
o.orderid = oi.orderid
group by c.customerid,c.customername)
select customerid,customername,revenue,
case 
when revenue >= 1000 then 'high value'
when revenue >= 500 then 'medium value'
else ' low value'
end as revenue_segmentation 
from customer_revenue
order by revenue desc;

-- Count Customers by Segment --

with customer_revenue as(
select c.customerid,c.customername,sum(oi.profit) as revenue 
from customers c 
join orders o
on  c.customerid= o.customerid
join order_items oi on
o.orderid = oi.orderid
group by c.customerid,c.customername),
customer_segment as (
select customerid,customername,revenue,
case 
when revenue >= 1000 then 'high value'
when revenue >= 500 then 'medium value'
else ' low value'
end as customer_segmentation 
from customer_revenue)
select customer_segmentation , count(*)as total_count,
round(sum(revenue),2) as segment
from customer_segment
group by customer_segmentation
order by segment desc;

-- Product Performance Analysis --
-- Product Sales & Quantity --
SELECT
    p.ProductID,
    p.ProductName,
    p.Category,
    SUM(oi.Quantity) AS TotalQuantitySold,
    SUM(oi.profit) AS TotalRevenue
FROM products p
JOIN order_items oi
    ON p.ProductID = oi.ProductID
GROUP BY
    p.ProductID,
    p.ProductName,
    p.Category
ORDER BY TotalRevenue DESC;

-- Top 10 Best-Selling Products by Quantity --
SELECT
    p.ProductID,
    p.ProductName,
    p.Category,
    SUM(oi.Quantity) AS TotalQuantitySold,
    SUM(oi.profit) AS TotalRevenue
FROM products p
JOIN order_items oi
    ON p.ProductID = oi.ProductID
GROUP BY
    p.ProductID,
    p.ProductName,
    p.Category
ORDER BY TotalQuantitySold DESC
LIMIT 10;

-- Product Revenue Ranking --
with product_revenue as (
select c.customerid, c.customername, sum(oi.profit) total_revenue
from customers c 
join orders o on c.customerid = o.customerid
join order_items oi on o.orderid = oi.orderid
group by c.customerid, c.customername)
select customerid, customername,total_revenue , rank() over (order by total_revenue) as revenue_rank
from product_revenue order by total_revenue desc ;

SELECT
    p.ProductID,
    p.ProductName,
    p.Category,
    SUM(oi.profit) AS TotalRevenue,
    RANK() OVER (
        ORDER BY SUM(oi.profit) DESC
    ) AS RevenueRank
FROM products p
JOIN order_items oi
    ON p.ProductID = oi.ProductID
GROUP BY
    p.ProductID,
    p.ProductName,
    p.Category
ORDER BY RevenueRank;

-- Top 3 Products Within Each Category --

SELECT
    p.ProductID,
    p.ProductName,
    p.Category,
    SUM(oi.profit) AS TotalRevenue
    
FROM products p
JOIN order_items oi
    ON p.ProductID = oi.ProductID
GROUP BY
    p.ProductID,
    p.ProductName,
    p.Category
ORDER BY totalrevenue desc 
limit 3;

WITH ProductRevenue AS (
    SELECT
        p.ProductID,
        p.ProductName,
        p.Category,
        SUM(oi.profit) AS TotalRevenue
    FROM products p
    JOIN order_items oi
        ON p.ProductID = oi.ProductID
    GROUP BY
        p.ProductID,
        p.ProductName,
        p.Category
),
RankedProducts AS (
    SELECT
        ProductID,
        ProductName,
        Category,
        TotalRevenue,
        ROW_NUMBER() OVER (
            PARTITION BY Category
            ORDER BY TotalRevenue DESC
        ) AS CategoryRank
    FROM ProductRevenue
)
SELECT
    ProductID,
    ProductName,
    Category,
    TotalRevenue,
    CategoryRank
FROM RankedProducts
WHERE CategoryRank <= 3
ORDER BY
    Category,
    CategoryRank;
    
    -- Revenue by Sales Channel --
    SELECT
    o.SalesChannel,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.Quantity) AS TotalQuantitySold,
    SUM(oi.profit) AS TotalRevenue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY
    o.SalesChannel
ORDER BY TotalRevenue DESC;

-- Sales Channel Order Percentage --
SELECT
    SalesChannel,
    COUNT(DISTINCT OrderID) AS TotalOrders,
    ROUND(
        COUNT(DISTINCT OrderID) * 100.0 /
        (SELECT COUNT(DISTINCT OrderID) FROM orders),
        2
    ) AS OrderPercentage
FROM orders
GROUP BY SalesChannel
ORDER BY OrderPercentage DESC;

-- Average Order Value (AOV) by Sales Channel --

SELECT
    o.SalesChannel,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.profit) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.OrderID),
        2
    ) AS AverageOrderValue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY
    o.SalesChannel
ORDER BY AverageOrderValue DESC;

-- Order Count by Status --
 SELECT
    OrderStatus,
    COUNT(DISTINCT OrderID) AS TotalOrders
FROM orders
GROUP BY OrderStatus
ORDER BY TotalOrders DESC;

 -- Revenue by Order Status --
 SELECT
    o.OrderStatus,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.profit) AS TotalRevenue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY o.OrderStatus
ORDER BY TotalRevenue DESC;

-- Order Status Percentage --
select orderstatus, count(distinct orderid) as total_count,
round( count(distinct orderid) * 100.0 / (select count(distinct orderid) from orders),2) as order_percenatge
from orders 
group by orderstatus
order by order_percenatge desc ; 

-- Payment Method Performance --
SELECT
    PaymentMethod,
    COUNT(DISTINCT OrderID) AS TotalOrders,
    SUM(Amount) AS TotalPaymentAmount,
    ROUND(AVG(Amount), 2) AS AveragePaymentAmount
FROM payment
GROUP BY PaymentMethod
ORDER BY TotalPaymentAmount DESC;

-- Payment Status Analysis --
 SELECT
    PaymentStatus,
    COUNT(*) AS PaymentCount,
    SUM(Amount) AS TotalAmount,
    ROUND(AVG(Amount), 2) AS AveragePaymentAmount
FROM payment
GROUP BY PaymentStatus
ORDER BY TotalAmount DESC;

-- Return Reasons -- 
SELECT
    ReturnReason,
    COUNT(*) AS ReturnCount,
    ROUND(
        COUNT(*) * 100.0 / (SELECT COUNT(*) FROM returns),
        2
    ) AS ReturnPercentage
FROM returns
GROUP BY ReturnReason
ORDER BY ReturnCount DESC;

-- Return Status Analysis --
use ecommerce_analytics_project;
SELECT
    ReturnStatus,
    COUNT(*) AS ReturnCount,
    ROUND(
        COUNT(*) * 100.0 /
        (SELECT COUNT(*) FROM returns),
        2
    ) AS ReturnPercentage
FROM returns
GROUP BY ReturnStatus
ORDER BY ReturnCount DESC;

-- Return Rate -
SELECT
    COUNT(DISTINCT r.OrderID) AS ReturnedOrders,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    ROUND(
        COUNT(DISTINCT r.OrderID) * 100.0 /
        NULLIF(COUNT(DISTINCT o.OrderID), 0),
        2
    ) AS ReturnRatePercent
FROM orders o
LEFT JOIN returns r
    ON o.OrderID = r.OrderID;
    
    -- Customer Geographic Analysis --
    -- Revenue by Region --
    
    SELECT
    c.Region,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    COUNT(DISTINCT c.CustomerID) AS TotalCustomers,
    SUM(oi.profit) AS TotalRevenue
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY c.Region
ORDER BY TotalRevenue DESC;

-- Revenue by City --
SELECT
    c.City,
    c.Region,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    COUNT(DISTINCT c.CustomerID) AS TotalCustomers,
    SUM(oi.profit) AS TotalRevenue
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY
    c.City,
    c.Region
ORDER BY TotalRevenue DESC
LIMIT 15;

-- State-wise Revenue Analysis --
SELECT
    c.State,
    c.Region,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    COUNT(DISTINCT c.CustomerID) AS TotalCustomers,
    SUM(oi.profit) AS TotalRevenue
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY
    c.State,
    c.Region
ORDER BY TotalRevenue DESC;

-- Average Order Value (AOV) --
SELECT
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.profit) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.OrderID),
        2
    ) AS AverageOrderValue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID;
    
    -- AOV by Region --
    SELECT
    c.Region,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    SUM(oi.profit) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.OrderID),
        2
    ) AS AverageOrderValue
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY c.Region
ORDER BY AverageOrderValue DESC;

-- Customer Order Frequency --
-- Average Orders per Customer --

SELECT
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    COUNT(DISTINCT c.CustomerID) AS PurchasingCustomers,
    ROUND(
        COUNT(DISTINCT o.OrderID) * 1.0 /
        COUNT(DISTINCT c.CustomerID),
        2
    ) AS AverageOrdersPerCustomer
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID;
    
    -- Customers by Purchase Frequency -- 
    select totalorders, count(*) as customercount
from (
select c.customerid, count(distinct o.orderid) as totalorders 
from customers c 
join orders o on c.customerid = o.customerid
group by c.customerid) frequent_customer
group by totalorders
order by totalorders;

-- Monthly Active Customers --

SELECT
    YEAR(o.OrderDate) AS SalesYear,
    MONTH(o.OrderDate) AS SalesMonth,
    MONTHNAME(o.OrderDate) AS MonthName,
    COUNT(DISTINCT o.CustomerID) AS ActiveCustomers
FROM orders o
WHERE o.OrderDate IS NOT NULL
GROUP BY
    YEAR(o.OrderDate),
    MONTH(o.OrderDate),
    MONTHNAME(o.OrderDate)
ORDER BY
    SalesYear,
    SalesMonth;
    
    -- Monthly Revenue per Active Customer --
    SELECT
    YEAR(o.OrderDate) AS SalesYear,
    MONTH(o.OrderDate) AS SalesMonth,
    MONTHNAME(o.OrderDate) AS MonthName,
    COUNT(DISTINCT o.CustomerID) AS ActiveCustomers,
    SUM(oi.profit) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.CustomerID),
        2
    ) AS RevenuePerCustomer
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
WHERE o.OrderDate IS NOT NULL
GROUP BY
    YEAR(o.OrderDate),
    MONTH(o.OrderDate),
    MONTHNAME(o.OrderDate)
ORDER BY
    SalesYear,
    SalesMonth;

-- Number of Active Months per Customer --
SELECT
    c.CustomerID,
    c.CustomerName,
    COUNT(DISTINCT DATE_FORMAT(o.OrderDate, '%Y-%m')) AS ActiveMonths,
    COUNT(DISTINCT o.OrderID) AS TotalOrders
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
WHERE o.OrderDate IS NOT NULL
GROUP BY
    c.CustomerID,
    c.CustomerName
ORDER BY ActiveMonths DESC;

-- Classify Customers by Retention --
SELECT
    c.CustomerID,
    c.CustomerName,
    COUNT(DISTINCT DATE_FORMAT(o.OrderDate, '%Y-%m')) AS ActiveMonths,
    CASE
        WHEN COUNT(DISTINCT DATE_FORMAT(o.OrderDate, '%Y-%m')) >= 6
            THEN 'Highly Active'
        WHEN COUNT(DISTINCT DATE_FORMAT(o.OrderDate, '%Y-%m')) >= 3
            THEN 'Moderately Active'
        ELSE 'Low Activity'
    END AS RetentionSegment
FROM customers c
JOIN orders o
    ON c.CustomerID = o.CustomerID
WHERE o.OrderDate IS NOT NULL
GROUP BY
    c.CustomerID,
    c.CustomerName
ORDER BY ActiveMonths DESC;
-- Retention Segment Summary --
WITH CustomerRetention AS (
    SELECT
        c.CustomerID,
        COUNT(DISTINCT DATE_FORMAT(o.OrderDate, '%Y-%m')) AS ActiveMonths
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY c.CustomerID
)
SELECT
    CASE
        WHEN ActiveMonths >= 6 THEN 'Highly Active'
        WHEN ActiveMonths >= 3 THEN 'Moderately Active'
        ELSE 'Low Activity'
    END AS RetentionSegment,
    COUNT(*) AS CustomerCount,
    ROUND(
        COUNT(*) * 100.0 / (SELECT COUNT(*) FROM CustomerRetention),
        2
    ) AS CustomerPercentage
FROM CustomerRetention
GROUP BY RetentionSegment
ORDER BY CustomerCount DESC;

-- Customer Cohort Analysis --
SELECT
    CohortMonth,
    COUNT(*) AS NewCustomers
FROM (
    SELECT
        CustomerID,
        DATE_FORMAT(MIN(OrderDate), '%Y-%m') AS CohortMonth
    FROM orders
    WHERE OrderDate IS NOT NULL
    GROUP BY CustomerID
) AS CustomerCohort
GROUP BY CohortMonth
ORDER BY CohortMonth;

-- Customer Retention by Cohort --

WITH CustomerOrders AS (
    SELECT
        CustomerID,
        COUNT(DISTINCT OrderID) AS TotalOrders,
        DATE_FORMAT(MIN(OrderDate), '%Y-%m') AS CohortMonth
    FROM orders
    WHERE OrderDate IS NOT NULL
    GROUP BY CustomerID
)
SELECT
    CohortMonth,
    COUNT(*) AS TotalCustomers,
    SUM(
        CASE
            WHEN TotalOrders > 1 THEN 1
            ELSE 0
        END
    ) AS RepeatCustomers,
    ROUND(
        SUM(
            CASE
                WHEN TotalOrders > 1 THEN 1
                ELSE 0
            END
        ) * 100.0 / COUNT(*),
        2
    ) AS RepeatCustomerPercentage
FROM CustomerOrders
GROUP BY CohortMonth
ORDER BY CohortMonth;
-- Repeat Purchase Rate --
WITH CustomerOrders AS (
    SELECT
        CustomerID,
        COUNT(DISTINCT OrderID) AS TotalOrders
    FROM orders
    GROUP BY CustomerID
)
SELECT
    COUNT(*) AS TotalPurchasingCustomers,
    SUM(
        CASE
            WHEN TotalOrders > 1 THEN 1
            ELSE 0
        END
    ) AS RepeatCustomers,
    ROUND(
        SUM(
            CASE
                WHEN TotalOrders > 1 THEN 1
                ELSE 0
            END
        ) * 100.0 / COUNT(*),
        2
    ) AS RepeatPurchaseRate
FROM CustomerOrders;

-- Customer Revenue by Purchase Frequency --
SELECT
    CustomerOrderCount,
    COUNT(*) AS CustomerCount,
    ROUND(SUM(CustomerRevenue), 2) AS TotalRevenue,
    ROUND(AVG(CustomerRevenue), 2) AS AverageRevenuePerCustomer
FROM (
    SELECT
        c.CustomerID,
        COUNT(DISTINCT o.OrderID) AS CustomerOrderCount,
        SUM(oi.profit) AS CustomerRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY c.CustomerID
) AS CustomerAnalysis
GROUP BY CustomerOrderCount
ORDER BY CustomerOrderCount;

-- Revenue Contribution by Customer Segment --
WITH CustomerRevenue AS (
    SELECT
        c.CustomerID,
        SUM(oi.profit) AS TotalRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY c.CustomerID
),
CustomerSegments AS (
    SELECT
        CustomerID,
        TotalRevenue,
        CASE
            WHEN TotalRevenue >= 10000 THEN 'High Value'
            WHEN TotalRevenue >= 5000 THEN 'Medium Value'
            ELSE 'Low Value'
        END AS CustomerSegment
    FROM CustomerRevenue
)
SELECT
    CustomerSegment,
    COUNT(*) AS CustomerCount,
    ROUND(SUM(TotalRevenue), 2) AS SegmentRevenue,
    ROUND(
        SUM(TotalRevenue) * 100.0 /
        (SELECT SUM(TotalRevenue) FROM CustomerSegments),
        2
    ) AS RevenuePercentage
FROM CustomerSegments
GROUP BY CustomerSegment
ORDER BY SegmentRevenue DESC;

-- Top 5 Products by Revenue-- 
select p.productname,sum(oi.profit) as total_revenue
from products p 
join order_items oi 
on 
p.productid = oi.productid
group by p.productname
order by total_revenue desc 
limit 10;

-- Product Revenue Contribution -- 
select p.productname,p.productid, sum(oi.profit) as total_revenue,
round (SUM(oi.quantity * oi.unitprice) * 100.0 /
        (SELECT SUM(quantity * unitprice)
         FROM Order_Items),
        2  ) AS revenue_percentage
from products p
join 	order_items oi on 
p.productid = oi.productid
 group by p. productid , p.productname
 order by total_revenue desc;
 
 -- Top 5 Products by Quantity Sold --
 
 SELECT
    p.productid,
    p.productname ,
    SUM(oi.quantity) AS total_quantity_sold
FROM Products p
JOIN Order_Items oi
    ON p.productid = oi.productid
GROUP BY
    p.productid,
    p.productname
ORDER BY total_quantity_sold DESC
LIMIT 5;

-- Average Selling Price per Product --
SELECT
    p.productid,
    p.productname,
    ROUND(AVG(oi.unitprice), 2) AS average_selling_price,
    SUM(oi.quantity) AS total_quantity_sold,
    SUM(oi.quantity * oi.unitprice) AS total_revenue
FROM Products p
JOIN Order_Items oi
    ON p.productid = oi.productid
GROUP BY
    p.productid,
    p.productname
ORDER BY average_selling_price DESC;

-- Product Sales by Category --
SELECT
    p.category,
    SUM(oi.quantity) AS total_quantity_sold,
    SUM(oi.quantity * oi.unitprice) AS total_revenue,
    ROUND(AVG(oi.unitprice), 2) AS average_price
FROM Products p
JOIN Order_Items oi
    ON p.productid = oi.productid
GROUP BY
    p.category
ORDER BY total_revenue DESC;

-- Category Revenue Percentage --

SELECT
    p.category,
    SUM(oi.quantity * oi.unitprice) AS category_revenue,
    ROUND(
        SUM(oi.quantity * oi.unitprice) * 100.0 /
        (SELECT SUM(quantity * unitprice)
         FROM Order_Items),
        2
    ) AS revenue_percentage
FROM Products p
JOIN Order_Items oi
    ON p.productid = oi.productid
GROUP BY
    p.category
ORDER BY category_revenue DESC;

-- Category Sales Ranking --
SELECT
    p.category,
    SUM(oi.quantity * oi.unitprice) AS total_revenue,
    RANK() OVER (
        ORDER BY SUM(oi.quantity * oi.unitprice) DESC
    ) AS revenue_rank
FROM Products p
JOIN Order_Items oi
    ON p.productid = oi.productid
GROUP BY
    p.category
ORDER BY revenue_rank;

-- Top Product Within Each Category --
WITH product_sales AS (
    SELECT
        p.productid,
        p.productname,
        p.category,
        SUM(oi.quantity * oi.unitprice) AS total_revenue
    FROM Products p
    JOIN Order_Items oi
        ON p.productid = oi.productid
    GROUP BY
        p.productid,
        p.productname,
        p.category
),
ranked_products AS (
    SELECT
        productid,
        productname,
        category,
        total_revenue,
        RANK() OVER (
            PARTITION BY category
            ORDER BY total_revenue DESC
        ) AS product_rank
    FROM product_sales
)
SELECT
    productid,
    productname,
    category,
    total_revenue,
    product_rank
FROM ranked_products
WHERE product_rank = 1
ORDER BY category;

-- Revenue by Customer Type -- 
-- One-Time Customers vs Repeat Customers --

WITH CustomerAnalysis AS (
    SELECT
        c.CustomerID,
        COUNT(DISTINCT o.OrderID) AS TotalOrders,
        SUM(oi.profit) AS CustomerRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY c.CustomerID
)
SELECT
    CASE
        WHEN TotalOrders = 1 THEN 'One-Time Customer'
        ELSE 'Repeat Customer'
    END AS CustomerType,
    COUNT(*) AS CustomerCount,
    ROUND(SUM(CustomerRevenue), 2) AS TotalRevenue,
    ROUND(AVG(CustomerRevenue), 2) AS AverageRevenuePerCustomer
FROM CustomerAnalysis
GROUP BY CustomerType
ORDER BY TotalRevenue DESC;

-- Average Revenue by Customer Type --
-- average order value generated by each customer type -- 
SELECT
    CASE
        WHEN TotalOrders = 1 THEN 'One-Time Customer'
        ELSE 'Repeat Customer'
    END AS CustomerType,
    COUNT(*) AS CustomerCount,
    ROUND(SUM(CustomerRevenue), 2) AS TotalRevenue,
    ROUND(AVG(CustomerRevenue), 2) AS AverageCustomerRevenue
FROM (
    SELECT
        c.CustomerID,
        COUNT(DISTINCT o.OrderID) AS TotalOrders,
        SUM(oi.profit) AS CustomerRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY c.CustomerID
) AS CustomerAnalysis
GROUP BY CustomerType
ORDER BY AverageCustomerRevenue DESC;

-- Monthly Revenue Growth -
WITH MonthlySales AS (
    SELECT
        YEAR(o.OrderDate) AS SalesYear,
        MONTH(o.OrderDate) AS SalesMonth,
        MONTHNAME(o.OrderDate) AS MonthName,
        SUM(oi.profit) AS MonthlyRevenue
    FROM orders o
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    WHERE o.OrderDate IS NOT NULL
    GROUP BY
        YEAR(o.OrderDate),
        MONTH(o.OrderDate),
        MONTHNAME(o.OrderDate)
),
MonthlyComparison AS (
    SELECT
        SalesYear,
        SalesMonth,
        MonthName,
        MonthlyRevenue,
        LAG(MonthlyRevenue) OVER (
            ORDER BY SalesYear, SalesMonth
        ) AS PreviousMonthRevenue
    FROM MonthlySales
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    ROUND(MonthlyRevenue, 2) AS MonthlyRevenue,
    ROUND(PreviousMonthRevenue, 2) AS PreviousMonthRevenue,
    ROUND(
        (MonthlyRevenue - PreviousMonthRevenue) * 100.0 /
        NULLIF(PreviousMonthRevenue, 0),
        2
    ) AS MoMGrowthPercent
FROM MonthlyComparison
ORDER BY SalesYear, SalesMonth;

-- Monthly Order Growth --
WITH MonthlyOrders AS (
    SELECT
        YEAR(OrderDate) AS SalesYear,
        MONTH(OrderDate) AS SalesMonth,
        MONTHNAME(OrderDate) AS MonthName,
        COUNT(DISTINCT OrderID) AS TotalOrders
    FROM orders
    WHERE OrderDate IS NOT NULL
    GROUP BY
        YEAR(OrderDate),
        MONTH(OrderDate),
        MONTHNAME(OrderDate)
),
OrderComparison AS (
    SELECT
        SalesYear,
        SalesMonth,
        MonthName,
        TotalOrders,
        LAG(TotalOrders) OVER (
            ORDER BY SalesYear, SalesMonth
        ) AS PreviousMonthOrders
    FROM MonthlyOrders
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    TotalOrders,
    PreviousMonthOrders,
    ROUND(
        (TotalOrders - PreviousMonthOrders) * 100.0 /
        NULLIF(PreviousMonthOrders, 0),
        2
    ) AS MoMOrderGrowthPercent
FROM OrderComparison
ORDER BY SalesYear, SalesMonth;

-- Monthly Active Customer Growth --
WITH MonthlyCustomers AS (
    SELECT
        YEAR(OrderDate) AS SalesYear,
        MONTH(OrderDate) AS SalesMonth,
        MONTHNAME(OrderDate) AS MonthName,
        COUNT(DISTINCT CustomerID) AS ActiveCustomers
    FROM orders
    WHERE OrderDate IS NOT NULL
    GROUP BY
        YEAR(OrderDate),
        MONTH(OrderDate),
        MONTHNAME(OrderDate)
),
CustomerComparison AS (
    SELECT
        SalesYear,
        SalesMonth,
        MonthName,
        ActiveCustomers,
        LAG(ActiveCustomers) OVER (
            ORDER BY SalesYear, SalesMonth
        ) AS PreviousMonthCustomers
    FROM MonthlyCustomers
)
SELECT
    SalesYear,
    SalesMonth,
    MonthName,
    ActiveCustomers,
    PreviousMonthCustomers,
    ROUND(
        (ActiveCustomers - PreviousMonthCustomers) * 100.0 /
        NULLIF(PreviousMonthCustomers, 0),
        2
    ) AS MoMCustomerGrowthPercent
FROM CustomerComparison
ORDER BY SalesYear, SalesMonth;
 -- Monthly Average Order Value --
 SELECT
    YEAR(o.OrderDate) AS SalesYear,
    MONTH(o.OrderDate) AS SalesMonth,
    MONTHNAME(o.OrderDate) AS MonthName,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    ROUND(SUM(oi.profit), 2) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.OrderID),
        2
    ) AS AverageOrderValue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
WHERE o.OrderDate IS NOT NULL
GROUP BY
    YEAR(o.OrderDate),
    MONTH(o.OrderDate),
    MONTHNAME(o.OrderDate)
ORDER BY
    SalesYear,
    SalesMonth;

-- Revenue by Order Status --
SELECT
    o.OrderStatus,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    ROUND(SUM(oi.profit), 2) AS TotalRevenue,
    ROUND(
        SUM(oi.profit) / COUNT(DISTINCT o.OrderID),
        2
    ) AS AverageOrderValue
FROM orders o
JOIN order_items oi
    ON o.OrderID = oi.OrderID
GROUP BY
    o.OrderStatus
ORDER BY TotalRevenue DESC;

-- Final SQL KPI: Overall Business Performance --
SELECT
    (SELECT COUNT(DISTINCT CustomerID)
     FROM customers) AS TotalCustomers,

    (SELECT COUNT(DISTINCT OrderID)
     FROM orders) AS TotalOrders,

    (SELECT COUNT(DISTINCT ProductID)
     FROM products) AS TotalProducts,

    (SELECT ROUND(SUM(profit), 2)
     FROM order_items) AS TotalRevenue,

    (SELECT ROUND(
        SUM(profit) / COUNT(DISTINCT OrderID), 2
    )
     FROM order_items) AS AverageOrderValue,

    (SELECT COUNT(*)
     FROM returns) AS TotalReturns;
     
     -- Customer Revenue Contribution --
     WITH CustomerRevenue AS (
    SELECT
        c.CustomerID,
        c.CustomerName,
        SUM(oi.profit) AS CustomerRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY
        c.CustomerID,
        c.CustomerName
)
SELECT
    CustomerID,
    CustomerName,
    ROUND(CustomerRevenue, 2) AS CustomerRevenue,
    ROUND(
        CustomerRevenue * 100.0 /
        (SELECT SUM(CustomerRevenue)
         FROM CustomerRevenue),
        2
    ) AS RevenueContributionPercent
FROM CustomerRevenue
ORDER BY CustomerRevenue DESC;

-- Top 10 Customers by Revenue Contribution --
WITH CustomerRevenue AS (
    SELECT
        c.CustomerID,
        c.CustomerName,
        COUNT(DISTINCT o.OrderID) AS TotalOrders,
        SUM(oi.profit) AS CustomerRevenue
    FROM customers c
    JOIN orders o
        ON c.CustomerID = o.CustomerID
    JOIN order_items oi
        ON o.OrderID = oi.OrderID
    GROUP BY
        c.CustomerID,
        c.CustomerName
)
SELECT
    CustomerID,
    CustomerName,
    TotalOrders,
    ROUND(CustomerRevenue, 2) AS CustomerRevenue,
    ROUND(
        CustomerRevenue * 100.0 /
        (SELECT SUM(CustomerRevenue)
         FROM CustomerRevenue),
        2
    ) AS RevenueContributionPercent
FROM CustomerRevenue
ORDER BY CustomerRevenue DESC
LIMIT 10;
 -- Product Revenue Contribution -- 
 WITH ProductRevenue AS (
    SELECT
        p.ProductID,
        p.ProductName,
        p.Category,
        SUM(oi.profit) AS ProductRevenue
    FROM products p
    JOIN order_items oi
        ON p.ProductID = oi.ProductID
    GROUP BY
        p.ProductID,
        p.ProductName,
        p.Category
)
SELECT
    ProductID,
    ProductName,
    Category,
    ROUND(ProductRevenue, 2) AS ProductRevenue,
    ROUND(
        ProductRevenue * 100.0 /
        (SELECT SUM(ProductRevenue)
         FROM ProductRevenue),
        2
    ) AS RevenueContributionPercent
FROM ProductRevenue
ORDER BY ProductRevenue DESC;

